    print(f"{r}: {' '.join(str(c) for c in row)}")

# Check the column distribution of the 7s pattern
cols_with_7s = set()
for r in range(18):
    for c in range(22):
        if grid[r][c] == 7:
            cols_with_7s.add(c)

print("Columns with 7s:", sorted(cols_with_7s))
print("Frequency per column:")
